argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'No visible Edge window'}
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$out=@()
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 $ct=$e.Current.ControlType.ProgrammaticName
 if($ct -match 'Button|Edit|Text'){
   $r=$e.Current.BoundingRectangle
   if($r.Y -gt 600 -and $r.Y -lt 900){
     $out += [pscustomobject]@{type=$ct;name=[string]$e.Current.Name;aid=[string]$e.Current.AutomationId;x=[int]$r.X;y=[int]$r.Y;w=[int]$r.Width;h=[int]$r.Height;focus=[bool]$e.Current.HasKeyboardFocus;enabled=[bool]$e.Current.IsEnabled}
   }
 }
}
$out | ConvertTo-Json -Depth 4 -Compress
